def stat(d):
    m = np.asarray(d['body_mass'], dtype=float)
    gm = np.mean(m, axis=1)
    return float(m.shape[1] * np.sum((gm - np.mean(m)) ** 2) / np.sum((m - np.mean(m)) ** 2))

